  // Apply NFKC normalization
  var nfkc = text.normalize('NFKC');
  // Apply NFD and remove combining marks U+0300-U+036F
  var nfd = nfkc.normalize('NFD');
  var stripped = nfd.replace(/[\u0300-\u036f]/g, '');
